public string GetApproximateVideoSize(YoutubeDlSubdata.Format Video) {
    if (DurationTime is null || Video.VideoBitrate is null) {
        return "null";
    }
    return "~" + (DurationTime.Value * (Video.VideoBitrate.Value / 8) * 1024).SizeToString();
}

